def control(obs):
    h = obs.get('hitch_deg', 0.0)
    status = obs.get('status', '')
    # Recover from the left-rail contact by moving forward slowly; forward motion
    # naturally straightens the trailer. Keep steering modest and favor the
    # open side indicated by the route.
