import math
def control(obs):
    lm=obs.get('local_map',{})
    L=lm.get('left_rail',[])
    R=lm.get('right_rail',[])
    def interp(points,u):
        if not points: return None
        points=sorted(points,key=lambda p:p[0])
        if u<=points[0][0]: return points[0][1]
        if u>=points[-1][0]: return points[-1][1]
        for a,b in zip(points,points[1:]):
            if a[0]<=u<=b[0]:
                f=(u-a[0])/(b[0]-a[0])
                return a[1]+f*(b[1]-a[1])
    vals=[]
    for u in (3,5,7):
        a,b=interp(L,u),interp(R,u)
        if a is not None and b is not None: vals.append((u,(a+b)/2))
    center=sum(v for u,v in vals)/len(vals) if vals else 0
    slope=(vals[-1][1]-vals[0][1])/(vals[-1][0]-vals[0][0]) if len(vals)>1 else 0
    hitch=obs.get('hitch_deg',0)
    steer=max(-22,min(22,-10*center-22*slope+0.65*hitch))
    return (steer,-0.85,180)

