    P=sorted(P,key=lambda q:q[0])
    if u<=P[0][0]:return P[0][1]
    if u>=P[-1][0]:return P[-1][1]
    for a,b in zip(P,P[1:]):
        if a[0]<=u<=b[0]:
            f=(u-a[0])/(b[0]-a[0]);return a[1]+f*(b[1]-a[1])
def control(obs):
    h=obs.get('hitch_deg',0.0)
    lm=obs.get('local_map',{});L=lm.get('left_rail',[]);R=lm.get('right_rail',[])
    if abs(h)>5:
        return (0,0.4,180)
    vals=[]
    for u in (2,4,6):
        a,b=at(L,u),at(R,u)
        if a is not None and b is not None: vals.append((u,(a+b)/2))
    c=sum(v for u,v in vals)/len(vals) if vals else 0
    s=(vals[-1][1]-vals[0][1])/(vals[-1][0]-vals[0][0]) if len(vals)>1 else 0
    steer=max(-7,min(7,-3*c-9*s+0.30*h))
    return (steer,-0.3,180)

