def control(obs):
    status=obs.get('status','')
    if status=='PINNED':
        return (-24.0,-0.10)
    h=obs.get('hitch_deg',0.0)
    m=obs.get('local_map',{})
    L=m.get('left_rail',[]) or []
    R=m.get('right_rail',[]) or []
    def at(points,u):
        return min(points,key=lambda p:abs(p[0]-u))[1] if points else None
    lv,rv=at(L,5.0),at(R,5.0)
    mid=(lv+rv)*0.5 if lv is not None and rv is not None else 0.0
    steer=max(-16.0,min(16.0,0.12*h-0.6*mid))
    return (steer,-0.08)

